import math

def compose(f, g):
    return lambda x: f(g(x))

def square(x):
    return x ** 2

def plus3(x):
    return x + 3

def minus4(x):
    return x - 4

print("f(x) = x^2 and g(x) = x + 3")
for x in [2, -3, 0]:
    print(f"  x = {x}: g first gives {plus3(x)}, then f gives {compose(square, plus3)(x)}")
    print(f"         f first gives {square(x)}, then g gives {compose(plus3, square)(x)}")
print("f(x) = sqrt(x) and g(x) = x - 4")
for x in [8, 4, 2]:
    inner = minus4(x)
    if inner < 0:
        print(f"  x = {x}: g(x) = {inner} < 0, so f(g(x)) is undefined")
    else:
        print(f"  x = {x}: g(x) = {inner}, f(g(x)) = {compose(math.sqrt, minus4)(x):.4f}")
    print(f"         g(f(x)) = sqrt({x}) - 4 = {compose(minus4, math.sqrt)(x):.4f}")

def first_collision(f):
    seen = {}
    for x in range(-10, 11):
        y = f(x)
        if y in seen:
            return f"f({seen[y]}) = f({x}) = {y}"
        seen[y] = x
    return ""

cases = [
    ("a line", lambda x: 2 * x + 1),
    ("a parabola", lambda x: x ** 2),
    ("a cube", lambda x: x ** 3),
    ("a constant", lambda x: 5),
    ("a parabola that hides its collision", lambda x: x ** 2 + x),
]
for label, f in cases:
    found = first_collision(f)
    if found == "":
        print(f"{label}: no collision from -10 to 10, so it may be one-to-one: prove it with algebra")
    else:
        print(f"{label}: {found}, so it's not one-to-one")

