count = int(input())
for i in range(count):
    a = int(input())
    b = int(input())
    c = int(input())
    message = "no collision found"
    seen = {}
    for x in range(-10, 11):
        y = a * x ** 3 + b * x ** 2 + c * x
        if message == "no collision found" and y in seen:
            message = f"f({seen[y]}) = f({x}) = {y}"
        seen[y] = x
    print(f"a = {a}, b = {b}, c = {c}: {message}")

from fractions import Fraction

count = int(input())
for i in range(count):
    a = int(input())
    b = int(input())
    print(f"({a}, {b}) mirrors to ({b}, {a})")
    if a == b:
        print("  on the line y = x")
    else:
        print(f"  midpoint ({Fraction(a + b, 2)}, {Fraction(a + b, 2)}), slope {Fraction(a - b, b - a)}")
